contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: order fields enough to construct a short put (isLong=false, isCall=false)
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 preMintAmount
    ) public payable {
        require(order.isLong == false && order.isCall == false, "test requires short put order");

        // Precondition: the order's baseAsset must be a contract for fillOrder to accept (per code)
        // We cannot create contracts here; rely on caller to pass a contract address or the check will revert.

        // Record pre-state visible values
        bytes32 orderHash = c.hashOrder(order);
        address maker = order.maker;
        uint256 positionIdBeforeBalanceCaller = 0; // meaningless placeholder; we will query owner after
        uint256 contractBalanceBefore = address(c).balance;

        bool reverted;
        // Call fillOrder sending ETH if caller provided payable amount (must match rules in contract)
        if (msg.value > 0) {
            require(address(this).balance >= msg.value, "insufficient balance for value");
        }

        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-call observations
        bool makerHasMintedToken;
        bool takerHasMintedToken;
        address ownerMakerPosition;
        address ownerTakerPosition;

        // The maker position id is uint256(orderHash)
        uint256 makerPositionId = uint256(orderHash);
        // The taker position id is uint256(hashOppositeOrder(order)) per fillOrder
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 takerPositionId = uint256(oppositeHash);

        // Try to read owners; if token not minted, ownerOf will revert — catch via try/catch
        try c.ownerOf(makerPositionId) returns (address ownerMaker) {
            ownerMakerPosition = ownerMaker;
            makerHasMintedToken = (ownerMaker != address(0));
        } catch {
            makerHasMintedToken = false;
            ownerMakerPosition = address(0);
        }

        try c.ownerOf(takerPositionId) returns (address ownerTaker) {
            ownerTakerPosition = ownerTaker;
            takerHasMintedToken = (ownerTaker != address(0));
        } catch {
            takerHasMintedToken = false;
            ownerTakerPosition = address(0);
        }

        uint256 contractBalanceAfter = address(c).balance;

        // General rule (single assert): If the fillOrder call did NOT revert and order is a short put,
        // then the contract's ETH balance increased by order.strike when native ETH was used (msg.value>0),
        // or (if no native ETH) the call should have succeeded only if the token transfers occurred —
        // we assert at least that when fillOrder succeeds and order.baseAsset == address(c.weth()) is false
        // then the caller minted both positions (maker and taker) as observable via ownerOf.
        // We express a robust general invariant: non-reverted fill of a short put results in both positions minted
        // and the maker owning the makerPositionId.

        // Note: We cannot refer to internal token balances, so we assert existence and owners of minted NFTs.
        assert(
            reverted || (
                makerHasMintedToken && takerHasMintedToken && ownerMakerPosition == maker
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an Order that is a long call and the floorAssetTokenIds required by exercise.
    // signature is unused because exercise doesn't verify signatures; the positions must already be minted
    // by prior calls, but per checker behavior the test can call c.fillOrder to create positions.
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 ethAmountForFill
    ) public payable {
        // Precondition: we require the order is a long call (isLong==true, isCall==true)
        require(order.isLong == true && order.isCall == true, "need long call order");

        // If we will send ETH to fillOrder, ensure this contract has enough balance to forward it
        if (ethAmountForFill > 0) require(address(this).balance >= ethAmountForFill, "insufficient balance");

        // Ensure baseAsset is a contract address so fillOrder won't revert on that check; caller must supply it
        // but we don't require here; if fillOrder reverts we'll capture that.

        // Derive orderHash and long position id
        bytes32 orderHash = c.hashOrder(order);
        uint256 longPositionId = uint256(orderHash);

        // Ensure the taker/maker positions do not already exist by attempting ownerOf (we'll ignore revert)
        bool preMinted = true;
        try c.ownerOf(longPositionId) returns (address) { preMinted = true; } catch { preMinted = false; }

        // If not pre-minted, attempt to mint both sides by calling fillOrder as maker->taker pair
        bool fillReverted = false;
        if (!preMinted) {
            try c.fillOrder{value: ethAmountForFill}(order, signature, floorAssetTokenIds) returns (uint256) {
                fillReverted = false;
            } catch {
                fillReverted = true;
            }
        }

        // Now attempt to exercise the long position by calling exercise; capture whether it reverted
        bool exerciseReverted;
        try c.exercise{value: 0}(order, floorAssetTokenIds) {
            exerciseReverted = false;
        } catch {
            exerciseReverted = true;
        }

        // Observe post-state: ownerOf(longPositionId) may revert if burned; exercisedPositions mapping is public
        bool ownerIsDead;
        bool exercisedFlag;

        // Check owner: ownerOf will revert if token not minted; but when burned, ownerOf also reverts per ERC721 (NOT_MINTED)
        // So to detect burnt token we check that calling ownerOf reverts OR returns address(0xdead) (but after transfer to 0xdead ownerOf returns 0xdead)
        // Per contract, exercise transfers token to address(0xdead) via transferFrom in exercise, so ownerOf should return 0xdead after successful exercise.
        // But ownerOf reverts if not minted; we handle both cases.
        try c.ownerOf(longPositionId) returns (address ownerAfter) {
            ownerIsDead = (ownerAfter == address(0xdead));
        } catch {
            ownerIsDead = false;
        }

        exercisedFlag = c.exercisedPositions(longPositionId);

        // General rule assertion:
        // If exercise did NOT revert, then the caller was owner and contract logic must have transferred the long position to 0xdead
        // and set exercisedPositions[longPositionId] = true.
        // We express that: not reverted => (owner is 0xdead OR exercisedPositions true). This allows either observation path
        // (owner observed as 0xdead, and exercisedPositions must be true). We assert both to be strict:
        assert(exerciseReverted || (ownerIsDead && exercisedFlag));
    }

    receive() external payable {}
}

