        require(order.isLong == true && order.isCall == true, "order must be long call");

        // If we will send ETH to fillOrder, ensure this contract has enough balance to forward it
        if (ethForFill > 0) require(address(this).balance >= ethForFill, "insufficient balance");

        // Derive the long position id
        bytes32 orderHash = c.hashOrder(order);
        uint256 longPositionId = uint256(orderHash);

        // Attempt to ensure the long position exists by calling fillOrder if ownerOf would revert.
        bool alreadyMinted = true;
        try c.ownerOf(longPositionId) returns (address) {
            alreadyMinted = true;
        } catch {
            alreadyMinted = false;
        }

        // If not minted, try to mint by calling fillOrder; this is a top-level state-changing call
        bool fillReverted;
        if (!alreadyMinted) {
            try c.fillOrder{value: ethForFill}(order, signature, floorAssetTokenIds) returns (uint256) {
                fillReverted = false;
            } catch {
                fillReverted = true;
            }
        } else {
            fillReverted = false;
        }

        // Now attempt to exercise the long position; this is the state-changing call under test
        bool exerciseReverted;
        try c.exercise{value: 0}(order, floorAssetTokenIds) {
            exerciseReverted = false;
        } catch {
            exerciseReverted = true;
        }

        // Observe ownerOf(longPositionId). If token exists, ownerOf returns address; if not minted it reverts.
        bool ownerIsDead = false;
        try c.ownerOf(longPositionId) returns (address ownerAfter) {
            ownerIsDead = (ownerAfter == address(0xdead));
        } catch {
            ownerIsDead = false;
        }

        // Observe exercisedPositions mapping (public getter)
        bool exercisedFlag = c.exercisedPositions(longPositionId);

        // General rule: If exercise did NOT revert, then owner must be 0xdead AND exercisedPositions must be true.
        // We allow that fillOrder may have reverted earlier; in that case exercise likely reverts too, so property
        // only claims the invariant when exercise itself succeeded.
        assert(exerciseReverted || (ownerIsDead && exercisedFlag));
    }

    receive() external payable {}
}

