contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept calldata inputs describing an Order and signature and floor ids and an ETH amount to send
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 ethAmount
    ) public payable {
        // preconditions for exercising the long-call path in fillOrder
        require(order.isLong && order.isCall, "must target long call path");
        // expiry must be in the future so fillOrder doesn't revert on expiration
        require(block.timestamp < order.expiration, "order expired");
        // duration bounded as in contract
        require(order.duration < 10_000 days, "duration too long");
        // baseAsset must be a contract address per fillOrder checks
        require(order.baseAsset.code.length > 0, "baseAsset not contract");
        // If ETH is provided, baseAsset must be weth
        if (ethAmount > 0) {
            require(order.baseAsset == c.weth(), "ETH only allowed when baseAsset is weth");
            require(address(this).balance >= ethAmount, "insufficient balance to send ETH");
        }
        // For long call, fillOrder requires floorAssetTokenIds.length == order.floorTokens.length
        require(floorAssetTokenIds.length == order.floorTokens.length, "floor length mismatch");

        // Read before-values
        bytes32 orderHash = c.hashOrder(order);
        uint256 longPositionId = uint256(orderHash);

        // Ensure positions not already minted: ownerOf would revert if minted; we check via try/catch
        bool longAlreadyMinted;
        try c.ownerOf(longPositionId) returns (address) {
            longAlreadyMinted = true;
        } catch {
            longAlreadyMinted = false;
        }

        // Also read previous expiration and stored floor ids (both public getters)
        uint256 prevExpiration = c.positionExpirations(longPositionId);
        uint256[] memory prevFloors = c.positionFloorAssetTokenIds(longPositionId);

        // Perform the fillOrder call, sending ETH if requested
        bool reverted;
        try c.fillOrder{value: ethAmount}(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if fillOrder did NOT revert, then
        // - the maker should own the token with id == orderHash
        // - the filler (this contract) should own the opposite position id (hashOppositeOrder)
        // - positionExpirations[longPositionId] == block.timestamp + order.duration
        // - positionFloorAssetTokenIds[longPositionId] equals the provided floorAssetTokenIds (if any)
        // We can only observe ownership via ownerOf for minted tokens; the filler minted token id is hashOppositeOrder

        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 oppositeId = uint256(oppositeHash);

        // Prepare checks but only assert a general conjunction once
        bool makerOwns;
        bool fillerOwns;
        bool expirationSetCorrectly;
        bool floorsStoredCorrectly;

        if (!reverted) {
            // maker should own token longPositionId
            address maker = order.maker;
            address ownerLong = c.ownerOf(longPositionId);
            makerOwns = (ownerLong == maker);

            // filler is msg.sender of fillOrder; in this test, msg.sender is this contract
            address ownerOpp = c.ownerOf(oppositeId);
            fillerOwns = (ownerOpp == address(this));

            // expiration for long position should be block.timestamp + duration
            uint256 exp = c.positionExpirations(longPositionId);
            expirationSetCorrectly = (exp == block.timestamp + order.duration);

            // floors stored should match input length and contents
            uint256[] memory stored = c.positionFloorAssetTokenIds(longPositionId);
            if (stored.length != floorAssetTokenIds.length) {
                floorsStoredCorrectly = false;
            } else {
                floorsStoredCorrectly = true;
                for (uint256 i = 0; i < stored.length; i++) {
                    if (stored[i] != floorAssetTokenIds[i]) {
                        floorsStoredCorrectly = false;
                        break;
                    }
                }
            }
        } else {
            // If reverted, we don't require any of the above; set all true so conjunction passes only when not reverted
            makerOwns = true;
            fillerOwns = true;
            expirationSetCorrectly = true;
            floorsStoredCorrectly = true;
        }

        // Final general assertion: either the call reverted, or all the expected state changes hold
        assert(reverted || (makerOwns && fillerOwns && expirationSetCorrectly && floorsStoredCorrectly));
    }

    receive() external payable {}
}

